    const next = { ...st, n: st.n + 1 };
    return { state: next, humanTasks: [ask(next, st.orderId)], output: { phase: 'reask', why: event.type } };
  }
  if (event.type === 'humanTask.timeout' || (event.type === 'timer.fired' && event.payload?.obligationId === 'deadline')) {
